$(() => {
  // 被绿灯扫描的变量的路径
  const pathsToScan = [
    'stat_data.World',
    'stat_data.Player'
  ];

  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, variables => {
    // 存放所有需要被扫描的变量的值
    const contentsToScan = [];

    // 遍历定义好的路径列表
    for (const path of pathsToScan) {
      // 使用 lodash 的 _.get 方法安全地获取变量值
      // 如果变量不存在，_.get 会返回 undefined，我们就可以跳过它
      const value = _.get(variables, path);

      if (value !== undefined) {
        // 如果变量存在，就把它转换成字符串并添加到数组中
        contentsToScan.push(JSON.stringify(value));
      }
    }

    // 4. 如果数组里有内容，就把它们用空格连接成一个大字符串，然后注入
    if (contentsToScan.length > 0) {
      const combinedContent = contentsToScan.join(' ');
      triggerSlash(`/inject position=none ephemeral=true scan=true id=variable "${combinedContent}"`);
    }
  });
});

