(function () {
    // Helper function: wraps numbers in a string with a styled <span>
    function formatNumbers(text, className = 'orange-digit') {
        const textStr = String(text);
        // This regex correctly finds numbers (including decimals) and avoids messing with HTML tags
        return textStr.replace(/(?<!<[^>]*?)(\d+(\.\d+)?)/g, `<span class="${className}">$1</span>`);
    }

    // Main function to update the status bar content
    function updateStatusBar() {
        // Find the last message's status bar. If it doesn't exist, do nothing.
        const $statusBar = $('.mes_block').last().find('.status-bar-container');
        if ($statusBar.length === 0) {
            return;
        }

        const allVars = getAllVariables();

        // Location and Time
        const location = _.get(allVars, 'stat_data.World.Location', '未知地点');
        const timeStr = _.get(allVars, 'stat_data.World.Time', '未知时间');
        $statusBar.find('#status-location').text(`[${location}]`);
        $statusBar.find('#status-time').html(formatNumbers(timeStr));

        // NPC Info dynamic visibility
        const $npcSection = $statusBar.find('#npc-info-section');
        const npcName = _.get(allVars, 'stat_data.World.CurrentNPC.Name', null);

        if (npcName === null || npcName === '无') {
            $npcSection.hide();
        } else {
            $npcSection.show();
            const npcRace = _.get(allVars, 'stat_data.World.CurrentNPC.Race', '未知');
            const npcSummary = _.get(allVars, 'stat_data.World.CurrentNPCOverview', '...');

            $statusBar.find('#npc-name').html(formatNumbers(npcName));
            $statusBar.find('#npc-race').html(formatNumbers(npcRace));
            $statusBar.find('#npc-summary').html(formatNumbers(npcSummary));
        }

        // Wallet (with specific gold color)
        const gold = _.get(allVars, 'stat_data.Player.Gold', 0);
        $statusBar.find('#player-gold').html(formatNumbers(gold, 'gold-amount'));

        // Backpack
        const $inventoryList = $statusBar.find('#inventory-list');
        const $backpackDetails = $statusBar.find('#backpack-details');
        $inventoryList.empty(); 

        const inventory = _.get(allVars, 'stat_data.Player.Inventory', {});
        const itemNames = Object.keys(inventory);

        if (itemNames.length === 0) {
            $inventoryList.removeClass('inventory-grid').addClass('empty-inventory').text('(背包是空的)');
            $backpackDetails.removeAttr('open');
        } else {
            $inventoryList.removeClass('empty-inventory').addClass('inventory-grid');
            itemNames.forEach(itemName => {
                const item = inventory[itemName];
                const quantity = _.get(item, 'Quantity', 1);
                const userDesc = _.get(item, 'UserDesc', '...');
                const isEquipped = _.get(item, 'Equipped', false);
                const equippedTag = isEquipped ? `<span class="equipped-tag">[已装备]</span>` : '';

                const itemHtml = `
                    <div>-</div>
                    <div class="item-name item-name-styled">${formatNumbers(itemName)}${equippedTag}</div>
                    <div class="item-quantity">x${formatNumbers(quantity)}</div>
                    <div>${formatNumbers(userDesc)}</div>
                `;
                $inventoryList.append(itemHtml);
            });
            $backpackDetails.attr('open', '');
        }
    }

    // THE MOST IMPORTANT PART: Listen for the MVU event
    // This ensures our script runs AFTER variables have been updated.
    eventOn('mag_variable_update_ended', updateStatusBar);

})();

